parameters.jsCode:
// Erst pruefen, dann bewerten. Was hier auffaellt, kostet spaeter im Ticket
// mehrere Rueckfragen: unplausible Bestellnummern, ein Bestelldatum in der
// Zukunft oder eine Beschreibung, die aus zwei Woertern besteht.
// Die Gewaehrleistungsfrist wird gleich mitgerechnet - sie entscheidet spaeter
// darueber, ob der Fall Anspruch oder Kulanz ist, und gehoert nicht in den
// Ermessensspielraum eines Sprachmodells.
const GEWAEHRLEISTUNG_MONATE = 24;
const MIN_BESCHREIBUNG = 20;

const e = $input.first().json;
const binaerdaten = $input.first().binary ?? {};

const bestellnummer = String(e['Bestellnummer'] ?? '').trim().toUpperCase();
const beschreibung = String(e['Was ist passiert?'] ?? '').trim();
const bestelldatum = new Date(e['Bestelldatum'] ?? '');
const heute = new Date();

const maengel = [];
// Zwei bis drei Buchstaben, optionaler Bindestrich, fuenf bis acht Ziffern -
// bei abweichendem Nummernkreis hier anpassen.
if (!/^[A-Z]{0,3}-?\d{5,8}$/.test(bestellnummer)) maengel.push('Die Bestellnummer sieht nicht wie eine unserer Nummern aus (Beispiel: AB-123456).');
if (isNaN(bestelldatum.getTime())) maengel.push('Das Bestelldatum konnte nicht gelesen werden.');
else if (bestelldatum > heute) maengel.push('Das Bestelldatum liegt in der Zukunft.');
if (beschreibung.length < MIN_BESCHREIBUNG) maengel.push('Die Beschreibung ist zu knapp, um den Fall einzuschaetzen.');

const tageSeitKauf = isNaN(bestelldatum.getTime()) ? null : Math.floor((heute - bestelldatum) / 86400000);
const fristEnde = new Date(bestelldatum);
fristEnde.setMonth(fristEnde.getMonth() + GEWAEHRLEISTUNG_MONATE);

return [{
  json: {
    bestellnummer,
    bestelldatum_de: isNaN(bestelldatum.getTime()) ? '' : bestelldatum.toLocaleDateString('de-DE'),
    tage_seit_kauf: tageSeitKauf,
    in_gewaehrleistung: !isNaN(bestelldatum.getTime()) && heute <= fristEnde,
    gewaehrleistung_bis_de: isNaN(fristEnde.getTime()) ? '' : fristEnde.toLocaleDateString('de-DE'),
    kunde: String(e['Ihr Name'] ?? '').trim(),
    email: String(e['E-Mail-Adresse'] ?? '').trim(),
    sachgebiet_kunde: e['Sachgebiet'] ?? 'Sonstiges',
    wunschloesung: e['Ihre Wunschloesung'] ?? 'Beratung, noch offen',
    beschreibung,
    anzahl_fotos: Object.keys(binaerdaten).length,
    hat_foto: Object.keys(binaerdaten).length > 0,
    eingang_iso: new Date().toISOString(),
    eingang_de: heute.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
    maengel,
    vollstaendig: maengel.length === 0
  }
}];

