// Die KI schlaegt einen Schweregrad vor, entschieden wird er hier. Bei Gefahr
// fuer Personen oder eingeschaltetem Anwalt darf die Einstufung nicht von einer
// Modellversion abhaengen - eine Wortliste ist in diesen Faellen das robustere
// Werkzeug. Sie kann nur nach oben korrigieren, nie nach unten.
const GEFAHR = /(verletz|verbrannt|verbrennung|brand|rauch|feuer|stromschlag|kurzschluss|explo|gesundheit|arzt|krankenhaus|schimmel|verdorben|allergisch|scharfe kante|umgekippt|abgebrochen und)/i;
const RECHTLICH = /(anwalt|rechtsanwalt|klage|verbraucherzentrale|presse|bewertung|widerruf|frist setze|letzte mahnung|gericht)/i;
const STILLSTAND = /(stillstand|produktion steht|ausfall|komplett defekt|geht gar nicht|totalausfall|baustelle steht)/i;

// Bearbeitungszeiten in Werktagen. Bewusst konservativ: eine gehaltene Frist
// beruhigt mehr als eine ehrgeizige, die reisst.
const FRISTEN = {
  kritisch: {werktage: 0, zusage: 'noch heute, spaetestens innerhalb von 4 Stunden', queue: 'Eskalation Teamleitung'},
  hoch:     {werktage: 1, zusage: 'innerhalb eines Werktags',                        queue: 'Prioritaet'},
  mittel:   {werktage: 2, zusage: 'innerhalb von zwei Werktagen',                    queue: 'Standard'},
  niedrig:  {werktage: 5, zusage: 'innerhalb von fuenf Werktagen',                   queue: 'Standard'}
};

// Samstag und Sonntag ueberspringen - sonst verspricht die Bestaetigung eine
// Rueckmeldung am Sonntag und der Kunde wartet umsonst.
function werktageAddieren(start, tage) {
  const d = new Date(start);
  let offen = tage;
  while (offen > 0) {
    d.setDate(d.getDate() + 1);
    if (d.getDay() !== 0 && d.getDay() !== 6) offen--;
  }
  return d;
}

const fall = $('Angaben pruefen').first().json;
const k = $input.first().json.message?.content ?? $input.first().json;
const text = `${fall.beschreibung} ${fall.sachgebiet_kunde}`;

let schweregrad = FRISTEN[k.schweregrad] ? k.schweregrad : 'mittel';
const eskalationsgruende = [];

if (GEFAHR.test(text)) { schweregrad = 'kritisch'; eskalationsgruende.push('Hinweis auf Gefahr fuer Personen oder Gesundheit'); }
if (RECHTLICH.test(text)) { schweregrad = 'kritisch'; eskalationsgruende.push('Rechtliche Schritte oder Oeffentlichkeit angekuendigt'); }
if (schweregrad !== 'kritisch' && STILLSTAND.test(text)) { schweregrad = 'hoch'; eskalationsgruende.push('Ausfall oder Stillstand beim Kunden'); }
if (Number(k.konfidenz ?? 0) < 0.6 && schweregrad === 'niedrig') { schweregrad = 'mittel'; eskalationsgruende.push('KI unsicher - Einstufung vorsichtshalber angehoben'); }

const frist = FRISTEN[schweregrad];
const faellig = schweregrad === 'kritisch'
  ? new Date(Date.now() + 4 * 60 * 60 * 1000)
  : werktageAddieren(new Date(), frist.werktage);

return [{
  json: {
    ...fall,
    schweregrad,
    kritisch: schweregrad === 'kritisch',
    sachgebiet: k.sachgebiet ?? 'Sonstiges',
    kurzfassung: k.kurzfassung ?? fall.beschreibung.slice(0, 120),
    kundenstimmung: k.kundenstimmung ?? 'sachlich',
    erwartete_kosten: k.erwartete_kosten ?? 'unklar',
    rueckfragen: Array.isArray(k.rueckfragen) ? k.rueckfragen : [],
    ki_konfidenz: Number(k.konfidenz ?? 0),
    ki_vorschlag: k.schweregrad ?? 'unbekannt',
    eskalationsgruende,
    regel_hat_korrigiert: eskalationsgruende.length > 0,
    queue: frist.queue,
    bearbeitungszeit_zusage: frist.zusage,
    faellig_de: faellig.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }),
    // Anspruch oder Kulanz - das entscheidet ueber die Formulierung im Ticket.
    anspruchsgrundlage: fall.in_gewaehrleistung ? 'Gewaehrleistung' : 'Kulanzpruefung noetig'
  }
}];

// Die Ticket-API antwortet nur mit ihrer eigenen Struktur - hier wird sie mit
// dem Fall zusammengefuehrt. Antwortet sie gar nicht oder ohne Nummer, laeuft
// der Vorgang trotzdem weiter: Der Kunde bekommt eine Ersatzkennung statt gar
// keiner Bestaetigung, und der Fehler steht im Ticket-Hinweis fuer das Team.
const fall = $('Eskalationsregeln anwenden').first().json;
const antwort = $input.first().json ?? {};

const nummer = antwort.ticket_id ?? antwort.id ?? antwort.number ?? antwort.ticketnummer ?? null;
const ersatz = 'VORL-' + fall.bestellnummer + '-' + new Date().toISOString().slice(0, 10).split('-').reverse().join('');

return [{
  json: {
    ...fall,
    ticketnummer: nummer ?? ersatz,
    ticket_angelegt: Boolean(nummer),
    ticket_hinweis: nummer ? '' : 'Ticketsystem hat keine Nummer geliefert - Fall bitte von Hand im System anlegen.'
  }
}];

